#!/usr/bin/env bash
# Generated by Cloudhop. Fixed steps for deploy, switch, rollback and destroy; no LLM decides anything here.
# The same script runs on GitHub Actions, GitLab CI, Bitbucket Pipelines and Azure Pipelines.
set -Eeuo pipefail # -E: switch's failure trap must also fire inside functions.

ACTION="$1"
CLOUD="$2"
SOURCE="${3:-}"

# Guardrail: anyone allowed to start this pipeline can pass any value, so only known actions and
# clouds get through. Everything below can then trust these three values.
case "$ACTION" in verify|plan|deploy|switch|rollback|destroy|report) ;; *) echo "Refusing unknown action '$ACTION'" >&2; exit 2 ;; esac
case "$CLOUD" in aws|gcp) ;; *) echo "Refusing unknown cloud '$CLOUD'" >&2; exit 2 ;; esac
case "$SOURCE" in ''|aws|gcp) ;; *) echo "Refusing unknown source cloud '$SOURCE'" >&2; exit 2 ;; esac
CONFIG=.cloudhop/config.json
SHA="${CLOUDHOP_SHA:-${GITHUB_SHA:-$(git rev-parse HEAD 2>/dev/null || echo local)}}"
RUN_ID="${CLOUDHOP_RUN_ID:-${GITHUB_RUN_ID:-}}"

cfg() { jq -r "$1" "$CONFIG"; }
NAME="$(cfg .name)"
HAS_DB="$(cfg .hasPostgres)"
log() { echo "::notice::$*"; }

# Guardrail: only clouds this project was connected to, as recorded in the reviewed config.
for cloud in "$CLOUD" $SOURCE; do
  [ "$(cfg ".clouds.$cloud != null")" = true ] || { echo "Refusing: $cloud is not connected to this project" >&2; exit 2; }
done

report() {
  local event="$1" cloud="$2" extra="${3:-{\}}"
  local body
  body="$(jq -n --arg event "$event" --arg cloud "$cloud" --arg run "$RUN_ID" --argjson extra "$extra" '{event: $event, cloud: $cloud, runId: $run} + $extra')"
  curl -fsS -m 20 -X POST "$(cfg .cloudhopUrl)/api/report" \
    -H "Authorization: Bearer ${CLOUDHOP_REPORT_TOKEN:-}" -H 'Content-Type: application/json' \
    -d "$body" >/dev/null || echo "::warning::Could not report to Cloudhop"
}

tf() { local cloud="$1"; shift; tofu -chdir=".cloudhop/infra/$cloud" "$@"; }

tf_init() {
  local cloud="$1"
  export TF_VAR_name="$NAME"
  TF_VAR_region="$(cfg ".clouds.$cloud.region")"
  export TF_VAR_region
  if [ "$cloud" = aws ]; then
    tf aws init -input=false -backend-config="bucket=$(cfg .clouds.aws.stateBucket)" \
      -backend-config="key=$NAME.tfstate" -backend-config="region=$TF_VAR_region"
  else
    TF_VAR_project="$(cfg .clouds.gcp.projectId)"
    export TF_VAR_project
    tf gcp init -input=false -backend-config="bucket=$(cfg .clouds.gcp.stateBucket)" -backend-config="prefix=$NAME"
  fi
}

out() { tf "$1" output -raw "$2"; }

site_url() {
  local ip
  ip="$(out "$1" public_ip)"
  echo "http://${ip//./-}.sslip.io" # Named host, because Cloudflare Workers cannot fetch bare IPs.
}

remote_aws() {
  local id status params
  params="$(jq -n --arg c "export HOME=/root; $1" '{commands: [$c], executionTimeout: ["3600"]}')"
  # Explicit return: callers use this inside `if`, where set -e does nothing and an empty id would loop forever.
  id="$(aws ssm send-command --instance-ids "$(out aws instance_id)" --document-name AWS-RunShellScript \
    --parameters "$params" --query Command.CommandId --output text)" || return 1
  while :; do
    sleep 5
    status="$(aws ssm get-command-invocation --command-id "$id" --instance-id "$(out aws instance_id)" --query Status --output text 2>/dev/null || echo Pending)"
    case "$status" in
      Success) aws ssm get-command-invocation --command-id "$id" --instance-id "$(out aws instance_id)" --query StandardOutputContent --output text; return 0 ;;
      Failed|Cancelled|TimedOut)
        aws ssm get-command-invocation --command-id "$id" --instance-id "$(out aws instance_id)" --query StandardErrorContent --output text >&2
        return 1 ;;
    esac
  done
}

remote_gcp() {
  gcloud compute ssh "$NAME-vm" --zone "$(out gcp zone)" --project "$(cfg .clouds.gcp.projectId)" \
    --tunnel-through-iap --quiet --command "sudo bash -c $(printf %q "$1")"
}

remote() { local cloud="$1"; shift; "remote_$cloud" "$1"; }

bucket_url() { [ "$1" = aws ] && echo "s3://$(out aws data_bucket)" || echo "gs://$(out gcp data_bucket)"; }
copy_cmd() { [ "$1" = aws ] && echo "aws s3 cp" || echo "gcloud storage cp"; }
remove_cmd() { [ "$1" = aws ] && echo "aws s3 rm" || echo "gcloud storage rm"; }

wait_ready() {
  local cloud="$1"
  for _ in $(seq 1 40); do
    if remote "$cloud" 'test -f /opt/cloudhop/ready' 2>/dev/null; then return 0; fi
    sleep 15
  done
  echo "VM on $cloud did not become ready" >&2
  return 1
}

# Images are built on the VM from the commit being deployed, so no registry or registry token is involved.
# Config and source go through the private bucket, so secrets never appear in remote command history.
prepare_vm() {
  local cloud="$1" bucket cp rm tmp
  bucket="$(bucket_url "$cloud")"
  cp="$(copy_cmd "$cloud")"
  rm="$(remove_cmd "$cloud")"
  tmp="$(mktemp)"
  {
    printf 'DB_PASSWORD=%s\nRELEASE=%s\n' "$(out "$cloud" db_password)" "$SHA"
    printf '%s\n' "${CLOUDHOP_ENV:-}"
  } > "$tmp"
  $cp "$tmp" "$bucket/deploy/.env"
  git archive --format=tar.gz -o "$tmp" HEAD
  $cp "$tmp" "$bucket/deploy/source.tgz"
  rm -f "$tmp"
  $cp .cloudhop/compose.yml "$bucket/deploy/compose.yml"
  remote "$cloud" "cd /opt/cloudhop && $cp $bucket/deploy/compose.yml compose.yml && $cp $bucket/deploy/.env .env && chmod 600 .env \
    && $cp $bucket/deploy/source.tgz /tmp/source.tgz && rm -rf src && mkdir src && tar -xzf /tmp/source.tgz -C src && rm -f /tmp/source.tgz \
    && docker compose build"
  $rm "$bucket/deploy/.env"
  $rm "$bucket/deploy/source.tgz"
}

start_app() { remote "$1" 'cd /opt/cloudhop && docker compose up -d'; }

# Stops app containers and keeps data containers running.
stop_app() { remote "$1" "cd /opt/cloudhop && docker compose ps --services | grep -vE '^(db|redis)$' | xargs -r docker compose stop"; }

check_health() {
  local url="$1" code
  for _ in $(seq 1 30); do
    code="$(curl -s -o /dev/null -m 5 -w '%{http_code}' "$url" || echo 000)"
    if [ "$code" != 000 ] && [ "$code" -lt 500 ]; then return 0; fi
    sleep 10
  done
  echo "$url did not respond with a healthy status" >&2
  return 1
}

provision() {
  tf_init "$1"
  tf "$1" apply -auto-approve -input=false
  wait_ready "$1"
}

copy_database() {
  local from="$1" to="$2" dump
  dump="$(mktemp)"
  remote "$from" "cd /opt/cloudhop && docker compose exec -T db pg_dump -U app -Fc app > /tmp/db.dump && $(copy_cmd "$from") /tmp/db.dump $(bucket_url "$from")/deploy/db.dump; code=\$?; rm -f /tmp/db.dump; exit \$code"
  $(copy_cmd "$from") "$(bucket_url "$from")/deploy/db.dump" "$dump"
  $(copy_cmd "$to") "$dump" "$(bucket_url "$to")/deploy/db.dump"
  rm -f "$dump"
  remote "$to" "cd /opt/cloudhop && docker compose up -d --wait db && $(copy_cmd "$to") $(bucket_url "$to")/deploy/db.dump /tmp/db.dump \
    && docker compose exec -T db pg_restore --clean --if-exists --no-owner --no-privileges -U app -d app < /tmp/db.dump; code=\$?; rm -f /tmp/db.dump; exit \$code"
  $(remove_cmd "$from") "$(bucket_url "$from")/deploy/db.dump"
  $(remove_cmd "$to") "$(bucket_url "$to")/deploy/db.dump"
}

do_deploy() {
  provision "$CLOUD"
  prepare_vm "$CLOUD"
  start_app "$CLOUD"
  local url
  url="$(site_url "$CLOUD")"
  check_health "$url"
  report deployed "$CLOUD" "$(jq -n --arg url "$url" '{url: $url}')"
  log "Live at $url"
}

# Offline dump and restore: writes stop for the whole copy. Source stays intact until destroyed separately.
do_switch() {
  [ -n "$SOURCE" ] && [ "$SOURCE" != "$CLOUD" ] || { echo "Switch needs a different source cloud" >&2; exit 1; }
  tf_init "$SOURCE"
  provision "$CLOUD"
  prepare_vm "$CLOUD"

  local started finished url
  started="$(date +%s)"
  restore_source() {
    echo "::error::Switch failed. Restarting app on $SOURCE."
    remote "$CLOUD" "cd /opt/cloudhop && docker compose stop" || true
    start_app "$SOURCE" || echo "::error::Could not restart $SOURCE. Check it now."
    report switch_failed "$SOURCE"
  }
  trap restore_source ERR
  stop_app "$SOURCE"
  if [ "$HAS_DB" = true ]; then copy_database "$SOURCE" "$CLOUD"; fi
  start_app "$CLOUD"
  url="$(site_url "$CLOUD")"
  check_health "$url"
  trap - ERR
  finished="$(date +%s)"
  report switched "$CLOUD" "$(jq -n --arg url "$url" --arg from "$SOURCE" --argjson seconds "$((finished - started))" '{url: $url, from: $from, downtimeSeconds: $seconds}')"
  log "Switched to $CLOUD in $((finished - started)) seconds of downtime. New address: $url. $SOURCE app is stopped and still billing until destroyed."
}

# Writes made on the current cloud since the switch stay there and are not copied back.
do_rollback() {
  tf_init "$CLOUD"
  tf_init "$SOURCE"
  stop_app "$SOURCE"
  start_app "$CLOUD"
  local url
  url="$(site_url "$CLOUD")"
  check_health "$url"
  report rolled_back "$CLOUD" "$(jq -n --arg url "$url" --arg from "$SOURCE" '{url: $url, from: $from}')"
}

collect_resources() {
  # Load as a share of CPU cores, memory and disk use on the VM. Shown on the Metrics tab.
  remote "$1" 'echo "{\"cpuLoadPercent\":$(awk -v n="$(nproc)" "{printf \"%.1f\", \$1/n*100}" /proc/loadavg),\"memoryPercent\":$(free | awk "/Mem:/{printf \"%.1f\", \$3/\$2*100}"),\"diskPercent\":$(df / --output=pcent | tail -1 | tr -dc 0-9)}"' | tail -1
}

do_report() {
  local extra='{}' resources
  tf_init "$CLOUD"
  resources="$(collect_resources "$CLOUD" | jq -c . 2>/dev/null || true)"
  extra="$(jq -n --argjson resources "${resources:-null}" '{resources: $resources}')"
  if [ "$CLOUD" = aws ]; then
    local cost credits
    cost="$(aws ce get-cost-and-usage --time-period "Start=$(date -u +%Y-%m-01),End=$(date -u -d tomorrow +%F)" --granularity MONTHLY --metrics UnblendedCost \
      --query 'ResultsByTime[0].Total.UnblendedCost.Amount' --output text || echo null)"
    credits="$(aws billing get-credits --account-id "$(aws sts get-caller-identity --query Account --output text)" --start-date "$(date -u -d '-300 days' +%s)" \
      --query 'credits[].{amount: remainingAmount.currencyAmount, ends: endDate}' --output json 2>/dev/null || echo null)"
    extra="$(jq -n --arg cost "$cost" --argjson credits "$credits" --argjson base "$extra" '$base + {costMonthToDate: ($cost | tonumber? // null), credits: $credits}')"
  fi
  report report "$CLOUD" "$extra"
}

# Asks the cloud which of these actions the deploy identity may do, and reports the answers.
# The first group should be allowed, the rest denied. Read-only; a failure here never fails the run.
AWS_CHECKS='ec2:RunInstances ec2:TerminateInstances ec2:AuthorizeSecurityGroupIngress ssm:SendCommand ce:GetCostAndUsage iam:CreateUser iam:CreateAccessKey iam:AttachUserPolicy iam:PutRolePolicy rds:DeleteDBInstance lambda:CreateFunction kms:ScheduleKeyDeletion organizations:LeaveOrganization'
GCP_CHECKS='["compute.instances.create","compute.instances.delete","compute.firewalls.create","storage.buckets.create","iam.serviceAccounts.actAs","resourcemanager.projects.setIamPolicy","resourcemanager.projects.delete","iam.serviceAccountKeys.create","cloudsql.instances.delete","container.clusters.delete","secretmanager.versions.access","bigquery.datasets.delete"]'
check_access() {
  local checks
  if [ "$CLOUD" = aws ]; then
    # IAM policy simulator, on this project's own deploy role (the role may simulate only itself).
    # shellcheck disable=SC2086 # AWS_CHECKS is a word list on purpose.
    checks="$(aws iam simulate-principal-policy --policy-source-arn "$(cfg .clouds.aws.roleArn)" --action-names $AWS_CHECKS \
      --query "EvaluationResults[].{action: EvalActionName, allowed: EvalDecision=='allowed'}" --output json)" || return 0
  else
    # Resource Manager testIamPermissions returns the subset of these the caller holds on the project.
    checks="$(curl -fsS -m 20 -X POST -H "Authorization: Bearer $(gcloud auth print-access-token)" -H 'Content-Type: application/json' \
      -d "$(jq -nc --argjson p "$GCP_CHECKS" '{permissions: $p}')" \
      "https://cloudresourcemanager.googleapis.com/v3/projects/$(cfg .clouds.gcp.projectId):testIamPermissions" \
      | jq -c --argjson p "$GCP_CHECKS" '(.permissions // []) as $held | [$p[] | {action: ., allowed: (. as $x | $held | index($x) != null)}]')" || return 0
  fi
  jq -e 'type == "array" and length > 0' >/dev/null 2>&1 <<<"$checks" || return 0
  report access "$CLOUD" "$(jq -nc --argjson checks "$checks" '{checks: $checks}')"
}

case "$ACTION" in
  verify)
    if [ "$CLOUD" = aws ]; then aws sts get-caller-identity; else gcloud projects describe "$(cfg .clouds.gcp.projectId)" --format='value(projectId)'; fi
    tf_init "$CLOUD"
    report verified "$CLOUD"
    check_access
    ;;
  plan) tf_init "$CLOUD"; tf "$CLOUD" plan -input=false ;;
  deploy) do_deploy ;;
  switch) do_switch ;;
  rollback) do_rollback ;;
  destroy) tf_init "$CLOUD"; tf "$CLOUD" destroy -auto-approve -input=false; report destroyed "$CLOUD" ;;
  report) do_report ;;
  *) echo "Unknown action $ACTION" >&2; exit 1 ;;
esac
